export function interpolateRustOwnedPath(method: RustOwnedMethodMetadata, request: unknown): string {
  let path = method.path;
  for (const parameter of method.pathParameters) {
    const key = parameter === "sha256hex" ? "versionSha256" : parameter;
    const value = (request as Record<string, unknown>)[key];
    if (value === undefined || value === null) throw new TypeError(`missing path parameter ${key}`);
    const rendered = value instanceof Uint8Array ? Array.from(value, byte => byte.toString(16).padStart(2, "0")).join("") : typeof value === "bigint" ? value.toString() : encodeURIComponent(String(value));
    path = path.replace(`{${parameter}}`, rendered);
  }
  return path;
}

export const RUST_OWNED_CREDENTIAL_POLICY = "bearer-no-crlf" as const;

export function validateRustOwnedCredentialPolicy(token: string): void {
  if ((RUST_OWNED_CREDENTIAL_POLICY as string) === "bearer-no-crlf") validateActorsCredential(token);
}

export function validateRustOwnedCredential(method: RustOwnedMethodMetadata, token: string): void {
  if ((method.credentialPolicy as string) === (RUST_OWNED_CREDENTIAL_POLICY as string)) validateRustOwnedCredentialPolicy(token);
}

